CREATE TABLE registration_event (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    created_at TIMESTAMP NOT NULL,
    updated_at TIMESTAMP NOT NULL,
    ip VARCHAR(45) NOT NULL,
    user_id BIGINT NOT NULL,
    success BOOLEAN NOT NULL,
    CONSTRAINT fk_registration_event_user
        FOREIGN KEY (user_id)
        REFERENCES users (id)
);

CREATE INDEX idx_reg_ip ON registration_event (ip);
CREATE INDEX idx_reg_user ON registration_event (user_id);
CREATE INDEX idx_reg_success ON registration_event (success);
CREATE INDEX idx_reg_created_at ON registration_event (created_at);
